public class CategoryPlot_removeDomainMarker_TriageGen0Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private maps of CategoryPlot using reflection,
     * since the provided API doesn't show a public way to populate these maps directly.
     */
    @SuppressWarnings("unchecked")
    private void injectMarkers(Layer layer, int index, ArrayList<Marker> markers) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundDomainMarkers" : "backgroundDomainMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        map.put(index, markers);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_WithNotify() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(Layer.FOREGROUND, index, markers);

        // We cannot easily verify fireChangeEvent() without a spy or custom subclass,
        // but we can verify the return value and state.
        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed", result);
        assertTrue("Markers list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Failure() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mock(Marker.class)); // Different marker
        injectMarkers(Layer.FOREGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Marker should not be removed", result);
        assertEquals("Markers list size should remain 1", 1, markers.size());
    }

    @Test
    public void testRemoveDomainMarker_Background_Success_NoNotify() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(Layer.BACKGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, false);

        assertTrue("Marker should be removed", result);
        assertTrue("Markers list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Background_Failure_NoNotify() throws Exception {
        int index = 1;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mock(Marker.class));
        injectMarkers(Layer.BACKGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, false);

        assertFalse("Marker should not be removed", result);
        assertEquals(1, markers.size());
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_NoNotify() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        injectMarkers(Layer.FOREGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, false);

        assertTrue("Marker should be removed", result);
        assertTrue(markers.isEmpty());
    }

    @Test(expected = NullPointerException.class)
    public void testRemoveDomainMarker_NullLayer_ThrowsException() {
        // This tests the branch where layer is neither FOREGROUND nor handled by the else block 
        // if the logic allowed, but here it tests the behavior of the existing code structure.
        plot.removeDomainMarker(0, mockMarker, null, true);
    }

    @Test(expected = NullPointerException.class)
    public void testRemoveDomainMarker_InvalidIndex_ThrowsException() throws Exception {
        // Testing access to a non-existent index in the map
        plot.removeDomainMarker(99, mockMarker, Layer.FOREGROUND, true);
    }
}
